cypress_script:
describe('Navigation between iframe example links', () => {
  it('should navigate to Nested Frames', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('Nested Frames').click();
    cy.url().should('include', '/nested_frames');
  });

  it('should not navigate on clicking a non-existent link', () => {
    cy.visit('https://the-internet.herokuapp.com/frames');
    cy.get('a').contains('Non-Existent Link').click();
    cy.url().should('not.include', '/nested_frames');
    cy.url().should('not.include', '/iframe');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Navigation between iframe example links', () => {
  test('should navigate to Nested Frames', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=Nested Frames');
    await expect(page).toHaveURL(/.*nested_frames/);
  });

  test('should not navigate on clicking a non-existent link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/frames');
    await page.click('text=Non-Existent Link');
    await expect(page).not.toHaveURL(/.*nested_frames/);
    await expect(page).not.toHaveURL(/.*iframe/);
  });
});
